def contains_duplicate(nums):
    n = len(nums)
    for i in range(n):                                     # try every index as the first value
        for j in range(i + 1, n):                            # try every later index as the second value
            if nums[i] == nums[j]:
                return True                                       # a matching pair was found
    return False


if __name__ == "__main__":
    nums = [1, 2, 3, 1]
    print(contains_duplicate(nums))

