import java.util.*;

public class Main {
    boolean containsDuplicate(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n; i++) {                             // try every index as the first value
            for (int j = i + 1; j < n; j++) {                       // try every later index as the second value
                if (nums[i] == nums[j]) {
                    return true;                                        // a matching pair was found
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        int[] nums = {1, 2, 3, 1};
        Main solution = new Main();
        System.out.println(solution.containsDuplicate(nums));
    }
}

