def contains_duplicate(nums):
    nums.sort()                                             # bring equal values next to each other
    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1]:
            return True                                          # two neighbors are equal
    return False


if __name__ == "__main__":
    nums = [4, 1, 2, 1]
    print(contains_duplicate(nums))

